    if (existing) return Promise.resolve(existing);
    return new Promise<Record>((resolveWaiter, reject) => {
      const timer = setTimeout(
        () => reject(new Error(`RPC wait timed out; last records: ${this.records.slice(-6).map((r) => r.type).join(", ")}`)),
        ms,
